class Kitap:
    def __init__(self, isbn, baslik):
        self.isbn = isbn
        self.baslik = baslik

    def __eq__(self, diger):
        return self.isbn == diger.isbn

k1 = Kitap('978-1', 'Nutuk')
k2 = Kitap('978-1', 'Nutuk')
print(k1 == k2)  # True (ISBN numaraları eşit olduğu için)

